80	     */
81	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
82	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
83	
84	    /**
85	     * The maximum number of owners a single city may contain. A create request for a city that
86	     * already holds this many owners is rejected with a 409 response.
87	     */
88	    private static final int MAX_OWNERS_PER_CITY = 50;
89	
90	    /**
91	     * The maximum number of owners that may be registered in a single day. A create request made
92	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
93	     * response.
94	     */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        normalizeAddress(ownerFieldsDto);
144	        validateRequiredFields(ownerFieldsDto);
145	        normalizeTelephone(ownerFieldsDto);
146	        rejectDuplicateTelephone(ownerFieldsDto);
147	        rejectDuplicateHousehold(ownerFieldsDto);
148	        rejectCityAtCapacity(ownerFieldsDto);
149	        resolveRegistrationDate(ownerFieldsDto);
150	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
151	        normalizeEmail(ownerFieldsDto);
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        assignCustomerCode(owner);
155	        assignMembershipNumber(owner);
156	        assignNamesakeCount(owner);
157	        assignHousehold(owner, ownerFieldsDto);
158	        this.clinicService.saveOwner(owner);
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        currentOwner.setAddress(ownerFieldsDto.getAddress());
173	        currentOwner.setCity(ownerFieldsDto.getCity());
174	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	        currentOwner.setLastName(ownerFieldsDto.getLastName());
176	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
177	        normalizeEmail(ownerFieldsDto);
178	        currentOwner.setEmail(ownerFieldsDto.getEmail());
179	        this.clinicService.saveOwner(currentOwner);
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Transactional
185	    @Override
186	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        this.clinicService.deleteOwner(owner);
192	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
