244	    }
245	
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner != null) {
252	            Pet pet = owner.getPet(petId);
253	            if (pet != null) {
254	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
255	            }
256	        }
257	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	    }
259	
260	    /**
261	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
262	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
263	     * does not catch). The names of all offending fields are collected so the caller receives a
264	     * 400 response whose {@code errors} array lists each one.
265	     */
266	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
267	        List<String> missingFields = new ArrayList<>();
268	        if (isBlank(ownerFieldsDto.getFirstName())) {
269	            missingFields.add("firstName");
270	        }
271	        if (isBlank(ownerFieldsDto.getLastName())) {
272	            missingFields.add("lastName");
273	        }
274	        if (isBlank(ownerFieldsDto.getAddress())) {
275	            missingFields.add("address");
276	        }
277	        if (isBlank(ownerFieldsDto.getCity())) {
278	            missingFields.add("city");
279	        }
280	        if (isBlank(ownerFieldsDto.getTelephone())) {
281	            missingFields.add("telephone");
282	        }
283	        if (!missingFields.isEmpty()) {
284	            throw new InvalidOwnerFieldsException(missingFields);
285	        }
286	    }
287	
288	    private static boolean isBlank(String value) {
289	        return value == null || value.trim().isEmpty();
290	    }
291	
292	    /**
293	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
294	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
295	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
296	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
297	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
298	     * means an address that is blank after normalization is rejected like a missing one.
299	     */
300	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
301	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
302	    }
303	
304	    /**
305	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
306	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
307	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
308	     * address is returned unchanged, making it safe to apply to stored values during comparison.
309	     */
310	    private static String canonicalAddress(String address) {
311	        if (address == null) {
312	            return null;
313	        }
314	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
315	        if (collapsed.isEmpty()) {
316	            return "";
317	        }
318	        String[] tokens = collapsed.split(" ");
319	        StringBuilder sb = new StringBuilder(collapsed.length());
320	        for (int i = 0; i < tokens.length; i++) {
321	            if (i > 0) {
322	                sb.append(' ');
323	            }
324	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
325	        }
326	        return sb.toString();
327	    }
328	
329	    /**
330	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
331	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
332	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
333	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
334	     * string is written back onto the request so it is what gets stored and returned. Any value that
335	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
336	     * names {@code telephone}.
337	     */
338	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
339	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
340	    }
341	
342	    /**
343	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
344	     * (400) naming {@code telephone} when it cannot form a valid number.
345	     */
346	    private static String toE164(String telephone) {
347	        if (telephone == null) {
348	            throw new InvalidOwnerFieldsException(List.of("telephone"));
349	        }
350	        boolean hasCountryCode = telephone.trim().startsWith("+");
351	        String digits = telephone.replaceAll("\\D", "");
352	        String national;
353	        if (hasCountryCode) {
354	            national = digits;
355	        } else {
356	            if (digits.startsWith("0")) {
357	                digits = digits.substring(1);
358	            }
359	            national = "61" + digits;
360	        }
361	        if (!national.matches("[0-9]{8,15}")) {
362	            throw new InvalidOwnerFieldsException(List.of("telephone"));
363	        }
364	        return "+" + national;
365	    }
366	
367	    /**
368	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
369	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
370	     * each existing owner's stored telephone is converted the same way before comparison so numbers
371	     * that only differ in formatting still collide. A match results in a 409 response naming
372	     * {@code telephone}.
373	     */
374	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
375	        String telephone = ownerFieldsDto.getTelephone();
376	        for (Owner existing : this.clinicService.findAllOwners()) {
377	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
378	                throw new DuplicateOwnerTelephoneException(telephone);
379	            }
380	        }
381	    }
382	
383	    /**
384	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
385	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
386	     */
387	    private static String normalizeExisting(String telephone) {
388	        try {
389	            return toE164(telephone);
390	        } catch (InvalidOwnerFieldsException ex) {
391	            return null;
392	        }
393	    }
394	
395	    /**
396	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
397	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
398	     * single space, so values that differ only in letter case or spacing still collide. When the
399	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
400	     * household members to share a name and address. A match results in a 409 response naming
401	     * {@code lastName} and {@code address}.
402	     */
403	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
404	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
405	            return;
406	        }
407	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
408	        String address = canonicalAddress(ownerFieldsDto.getAddress());
409	        for (Owner existing : this.clinicService.findAllOwners()) {
410	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
411	                && address.equals(canonicalAddress(existing.getAddress()))) {
412	                throw new DuplicateOwnerHouseholdException(
413	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
414	            }
415	        }
416	    }
417	
418	    /**
419	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
420	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
421	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
422	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
423	     */
424	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
425	        String city = ownerFieldsDto.getCity();
426	        int count = 0;
427	        for (Owner existing : this.clinicService.findAllOwners()) {
428	            if (city.equalsIgnoreCase(existing.getCity())) {
429	                count++;
430	            }
431	        }
432	        if (count >= MAX_OWNERS_PER_CITY) {
433	            throw new OwnerCityAtCapacityException(city);
434	        }
435	    }
436	
437	    /**
438	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
439	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
440	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
441	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
442	     */
443	    private void rejectDailyLimitReached(LocalDate registrationDate) {
444	        int count = 0;
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (registrationDate.equals(existing.getRegistrationDate())) {
447	                count++;
448	            }
449	        }
450	        if (count >= MAX_OWNERS_PER_DAY) {
451	            throw new DailyOwnerLimitReachedException(registrationDate);
452	        }
453	    }
454	
455	    /**
456	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
457	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
458	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
459	     */
460	    private static String normalizeForComparison(String value) {
461	        if (value == null) {
462	            return "";
463	        }
464	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
465	    }
466	
467	    /**
468	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
469	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
470	     * written back onto the request so that is what gets stored and returned. A present but invalid
471	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
472	     */
473	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
474	        String email = ownerFieldsDto.getEmail();
475	        if (email == null) {
476	            return;
477	        }
478	        String trimmed = email.trim();
479	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
480	            throw new InvalidOwnerFieldsException(List.of("email"));
481	        }
482	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
483	    }
484	
485	    /**
486	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
487	     * day. When the caller supplies no value it defaults to the server's current date; a value
488	     * provided in the request is kept. The effective date, whether supplied or defaulted, must fall
489	     * on a business day: a Saturday or Sunday is rolled forward to the following Monday. The adjusted
490	     * date is written back onto the request so it is what gets stored and returned (in ISO
491	     * {@code YYYY-MM-DD} format) and what every value derived from the registration date is based on.
492	     */
493	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
494	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
495	        if (effective == null) {
496	            effective = LocalDate.now();
497	        }
498	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
499	    }
500	
501	    /**
502	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
503	     * Monday; a weekday is returned unchanged.
504	     */
505	    private static LocalDate toBusinessDay(LocalDate date) {
506	        return switch (date.getDayOfWeek()) {
507	            case SATURDAY -> date.plusDays(2);
508	            case SUNDAY -> date.plusDays(1);
509	            default -> date;
510	        };
511	    }
512	
513	    /**
514	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
515	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
516	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
517	     * zero-padded sequence equal to one more than the number of owners already in that city
518	     * (e.g. {@code 'SYD-SMI-0007'}).
519	     */
520	    private void assignCustomerCode(Owner owner) {
521	        String city = owner.getCity();
522	        String lastName = owner.getLastName();
523	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
524	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
525	        int sequence = 1;
526	        for (Owner existing : this.clinicService.findAllOwners()) {
527	            if (city.equalsIgnoreCase(existing.getCity())) {
528	                sequence++;
529	            }
530	        }
531	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
532	    }
533	
534	    /**
535	     * Assigns the owner's {@code membershipNumber} on create, formatted
536	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
537	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
538	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
539	     * inputs are present.
540	     */
541	    private void assignMembershipNumber(Owner owner) {
542	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
543	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
544	    }
545	
546	    /**
547	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
548	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
549	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
550	     */
551	    private void assignNamesakeCount(Owner owner) {
552	        String firstName = owner.getFirstName();
553	        String lastName = owner.getLastName();
554	        int count = 0;
555	        for (Owner existing : this.clinicService.findAllOwners()) {
556	            if (firstName.equalsIgnoreCase(existing.getFirstName())
557	                && lastName.equalsIgnoreCase(existing.getLastName())) {
558	                count++;
559	            }
560	        }
561	        owner.setNamesakeCount(count);
562	    }
563	
564	    /**
565	     * Assigns the new owner's {@code householdId} when the request opts in with
566	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
567	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
568	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
569	     * all end up carrying one stable shared identifier: if any existing member already has a
570	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
571	     * and address. Any existing member that is missing the identifier is updated so the whole
572	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
573	     * identifier is assigned.
574	     */
575	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
576	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
577	            return;
578	        }
579	        String lastName = normalizeForComparison(owner.getLastName());
580	        String address = canonicalAddress(owner.getAddress());
581	        List<Owner> members = new ArrayList<>();
582	        for (Owner existing : this.clinicService.findAllOwners()) {
583	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
584	                && address.equals(canonicalAddress(existing.getAddress()))) {
585	                members.add(existing);
586	            }
587	        }
588	        if (members.isEmpty()) {
589	            return;
590	        }
591	        String householdId = members.stream()
592	            .map(Owner::getHouseholdId)
593	            .filter(id -> id != null && !id.isBlank())
594	            .findFirst()
595	            .orElseGet(() -> newHouseholdId(lastName, address));
596	        owner.setHouseholdId(householdId);
597	        for (Owner member : members) {
598	            if (!householdId.equals(member.getHouseholdId())) {
599	                member.setHouseholdId(householdId);
600	                this.clinicService.saveOwner(member);
601	            }
602	        }
603	    }
604	
605	    /**
606	     * Derives a stable household identifier from the normalized last name and address: the first
607	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
608	     * owners in the same household therefore derive the same value regardless of creation order.
609	     */
610	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
611	        try {
612	            byte[] digest = MessageDigest.getInstance("SHA-256")
613	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
614	            StringBuilder hex = new StringBuilder(digest.length * 2);
615	            for (byte b : digest) {
616	                hex.append(String.format("%02x", b));
617	            }
618	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
619	        } catch (NoSuchAlgorithmException ex) {
620	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
621	        }
622	    }
623	}
